import type { MetadataRoute } from "next";
import { APP_DESCRIPTION, APP_NAME } from "@/lib/config";

// Generated by Next rather than hand-written as public/manifest.webmanifest,
// so the colours below can't drift from the theme tokens they're meant to
// match - and so the <link rel="manifest"> is emitted automatically instead
// of being declared separately in the metadata export.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: APP_NAME,
    short_name: APP_NAME,
    description: APP_DESCRIPTION,
    start_url: "/",
    scope: "/",
    display: "standalone",
    // Both are the dark scheme's page surface (m3Dark.surface). background_color
    // paints the splash screen an installed app shows before first paint, and
    // theme_color the system chrome around it; picking the brand teal for
    // either makes the launch flash a colour the app itself never shows.
    background_color: "#0B1418",
    theme_color: "#0B1418",
    // A plain ("any") and a maskable icon at each of 192 and 512px, as
    // separate entries. Chrome won't offer to install the app without an
    // "any" icon of at least 144px - with only the maskable pair listed, its
    // installability check failed with manifest-missing-suitable-icon. All
    // of them are rendered from favicon.svg: the "any" pair transparent, the
    // maskable pair on the white full-bleed background launchers crop, with
    // the logo inside the central 80% safe zone.
    icons: [
      {
        src: "/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/web-app-manifest-192x192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "maskable",
      },
      {
        src: "/web-app-manifest-512x512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
